import React, { useState, useEffect, useRef } from 'react';
import { io } from 'socket.io-client';

function LaptopWebcamFeed() {
  const videoRef = useRef(null);
  const containerRef = useRef(null);
  const [error, setError] = useState(null);
  const [isFullscreen, setIsFullscreen] = useState(false);

  useEffect(() => {
    navigator.mediaDevices.getUserMedia({ video: true })
      .then(stream => {
        if (videoRef.current) videoRef.current.srcObject = stream;
      })
      .catch(() => setError("Camera permission denied or camera in use."));

    const handleFullscreenChange = () => {
      setIsFullscreen(!!document.fullscreenElement);
    };

    document.addEventListener('fullscreenchange', handleFullscreenChange);

    return () => {
      document.removeEventListener('fullscreenchange', handleFullscreenChange);
      if (videoRef.current && videoRef.current.srcObject) {
        videoRef.current.srcObject.getTracks().forEach(track => track.stop());
      }
    };
  }, []);

  const toggleFullscreen = () => {
    if (!containerRef.current) return;

    if (!document.fullscreenElement) {
      containerRef.current.requestFullscreen().catch(err => {
        console.error("Error attempting to enable full-screen mode:", err);
      });
    } else {
      document.exitFullscreen().catch(err => {
        console.error("Error attempting to exit full-screen mode:", err);
      });
    }
  };

  if (error) return <div style={{ color: '#f87171', padding: '1rem', textAlign: 'center' }}>{error}</div>;

  return (
    <div
      ref={containerRef}
      style={{
        position: 'relative',
        width: '100%',
        height: isFullscreen ? '100vh' : '220px',
        backgroundColor: '#000',
        borderRadius: isFullscreen ? '0px' : '8px',
        overflow: 'hidden'
      }}
    >
      <video
        ref={videoRef}
        autoPlay
        playsInline
        muted
        style={{ width: '100%', height: '100%', objectFit: 'cover' }}
      />

      {/* Control Buttons Overlay */}
      <div style={{
        position: 'absolute',
        top: '10px',
        right: '10px',
        display: 'flex',
        gap: '8px',
        zIndex: 20
      }}>
        <button
          onClick={toggleFullscreen}
          style={{
            background: 'rgba(15, 23, 42, 0.8)',
            color: '#fff',
            border: '1px solid rgba(255, 255, 255, 0.2)',
            borderRadius: '6px',
            padding: '6px 12px',
            fontSize: '0.8rem',
            cursor: 'pointer',
            display: 'flex',
            alignItems: 'center',
            gap: '4px',
            backdropFilter: 'blur(4px)'
          }}
        >
          {isFullscreen ? '🗗 Minimize' : '⛶ Fullscreen'}
        </button>
      </div>
    </div>
  );
}

export default function Dashboard({ token }) {
  const [cameras, setCameras] = useState([]);
  const [userEmail, setUserEmail] = useState('');
  const [emailSavedMsg, setEmailSavedMsg] = useState('');
  const [evidenceLogs, setEvidenceLogs] = useState([]);

  useEffect(() => {
    if ('Notification' in window && Notification.permission !== 'granted') {
      Notification.requestPermission();
    }

    fetch('http://localhost:5000/api/cameras', {
      headers: { 'Authorization': `Bearer ${token}` }
    })
      .then(res => res.json())
      .then(data => setCameras(Array.isArray(data) ? data : []))
      .catch(() => setCameras([]));

    fetch('http://localhost:5000/api/settings', {
      headers: { 'Authorization': `Bearer ${token}` }
    })
      .then(res => res.json())
      .then(data => setUserEmail(data.email || ''))
      .catch(err => console.error(err));

    fetch('http://localhost:5000/api/evidence', {
      headers: { 'Authorization': `Bearer ${token}` }
    })
      .then(res => res.json())
      .then(data => setEvidenceLogs(Array.isArray(data) ? data : []))
      .catch(() => setEvidenceLogs([]));

    const socket = io('http://localhost:5000');
    socket.on('new-alert', (newLog) => {
      setEvidenceLogs(prev => [newLog, ...(Array.isArray(prev) ? prev : [])]);

      if (Notification.permission === 'granted') {
        new Notification("🚨 AI Security Detection", {
          body: `${newLog.alertType} detected on ${newLog.cameraName}`,
        });
      }
    });

    return () => socket.disconnect();
  }, [token]);

  const handleSaveEmail = (e) => {
    e.preventDefault();
    fetch('http://localhost:5000/api/settings', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${token}` },
      body: JSON.stringify({ email: userEmail })
    }).then(() => {
      setEmailSavedMsg('Notification email saved successfully!');
      setTimeout(() => setEmailSavedMsg(''), 3000);
    });
  };

  const handleDeleteCamera = (id) => {
    fetch(`http://localhost:5000/api/cameras/${id}`, {
      method: 'DELETE',
      headers: { 'Authorization': `Bearer ${token}` }
    }).then(() => {
      setCameras(prev => (Array.isArray(prev) ? prev.filter(c => c.id !== id) : []));
    });
  };

  const safeLogs = Array.isArray(evidenceLogs) ? evidenceLogs : [];
  const safeCameras = Array.isArray(cameras) ? cameras : [];

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '2rem' }}>

      {/* EMAIL CONFIGURATION CARD */}
      <div className="card" style={{ background: '#1e293b', borderLeft: '4px solid #38bdf8' }}>
        <h3>⚙️ Alert Notification Settings</h3>
        <p style={{ color: '#94a3b8', fontSize: '0.9rem', margin: '0.5rem 0 1rem 0' }}>
          Configure recipient email address for detection incident logs.
        </p>

        {emailSavedMsg && <div className="message-banner success">{emailSavedMsg}</div>}

        <form onSubmit={handleSaveEmail} style={{ display: 'flex', gap: '1rem', alignItems: 'center' }}>
          <div className="form-group" style={{ flex: 1, marginBottom: 0 }}>
            <input
              type="email"
              placeholder="user@example.com"
              value={userEmail}
              onChange={e => setUserEmail(e.target.value)}
              required
            />
          </div>
          <button type="submit" className="btn-primary" style={{ width: 'auto', marginTop: 0, padding: '0.75rem 1.5rem' }}>
            Save Email
          </button>
        </form>
      </div>

      {/* CAMERA STREAMS SECTION */}
      <div>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem' }}>
          <h2>Live CCTV Stream Feeds ({safeCameras.length})</h2>
          <span style={{ color: '#34d399', fontWeight: '600' }}>● AI Vision Active</span>
        </div>

        {safeCameras.length === 0 ? (
          <div className="card" style={{ textAlign: 'center', padding: '3rem' }}>
            <p style={{ color: '#94a3b8' }}>No camera feeds connected.</p>
          </div>
        ) : (
          <div className="camera-grid" style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(320px, 1fr))', gap: '1.5rem' }}>
            {safeCameras.map((cam) => (
              <div key={cam.id} className="card camera-card" style={{ padding: '1rem' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '0.75rem' }}>
                  <h3 style={{ fontSize: '1.1rem' }}>{cam.name}</h3>
                  <span className="location-badge">{cam.locationType}</span>
                </div>

                <div className="feed-box" style={{ padding: 0 }}>
                  {cam.rtspUrl === '0' ? <LaptopWebcamFeed /> : <div style={{ padding: '2rem', textAlign: 'center' }}>RTSP Stream: {cam.rtspUrl}</div>}
                </div>

                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: '0.75rem' }}>
                  <p style={{ fontSize: '0.8rem', color: '#64748b' }}>
                    Source: {cam.rtspUrl === '0' ? 'Integrated Webcam' : cam.rtspUrl}
                  </p>
                  <button onClick={() => handleDeleteCamera(cam.id)} style={{ background: 'none', border: 'none', color: '#f87171', cursor: 'pointer', fontSize: '0.8rem' }}>
                    Remove
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* LIVE INCIDENT INCIDENT LOGS TABLE */}
      <div className="card" style={{ background: '#0f172a' }}>
        <h3 style={{ color: '#38bdf8', marginBottom: '1rem' }}>🚨 AI Detection Event Logs</h3>
        {safeLogs.length === 0 ? (
          <p style={{ color: '#64748b' }}>No threat detections recorded yet. Run detector.py and show a knife, helmet, or flame to trigger!</p>
        ) : (
          <div style={{ overflowX: 'auto' }}>
            <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
              <thead>
                <tr style={{ borderBottom: '1px solid #334155', color: '#94a3b8' }}>
                  <th style={{ padding: '0.75rem' }}>Time</th>
                  <th style={{ padding: '0.75rem' }}>Camera</th>
                  <th style={{ padding: '0.75rem' }}>Threat Detected</th>
                  <th style={{ padding: '0.75rem' }}>Status</th>
                </tr>
              </thead>
              <tbody>
                {safeLogs.map((log, index) => (
                  <tr key={index} style={{ borderBottom: '1px solid #1e293b' }}>
                    <td style={{ padding: '0.75rem', color: '#cbd5e1' }}>{new Date(log.timestamp).toLocaleTimeString()}</td>
                    <td style={{ padding: '0.75rem', color: '#cbd5e1' }}>{log.cameraName}</td>
                    <td style={{ padding: '0.75rem', color: '#ef4444', fontWeight: 'bold' }}>{log.alertType}</td>
                    <td style={{ padding: '0.75rem' }}><span style={{ background: '#991b1b', color: '#fca5a5', padding: '0.2rem 0.5rem', borderRadius: '4px', fontSize: '0.75rem' }}>ACTIVE ALERT</span></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

    </div>
  );
}
